import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order (people in list order, each
 *  person's newest claim first), so their numbers follow that order. Each is opened as a single
 *  open would be — its own audit line, then the figures it moved; one that cannot be opened (or is
 *  not on the sheet) is left as it is and counted as refused. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpen bulk, Claims claims, People people,
            Sheets sheets, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            Audit audit, Out<BulkOpenResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.OPEN, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        int opened = 0;
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
                Claim claim = claims.find(sheetId, listed.getId());
                Snapshot before = rollup.snapshot(sheetId);
                try {
                    apply.apply(change, claim, sheets, people, figures, closedPeriods, settings);
                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                    continue;
                }
                claims.save(claim);
                record.record(change, claim, people, audit);
                rollup.record(sheetId, before, bulk.user());
                opened++;
            }
        }
        result.set(new BulkOpenResult(opened, bulk.claimIds().size() - opened));
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The sheets and their "today". A sheet starts with the real date the first time it is loaded;
 * from then on {@link #today(String)} is the only date the app uses for that sheet — never the
 * real clock.
 */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today, starting the sheet at the real date when it has never been used. */
    public LocalDate today(String sheetId) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, ? FROM DUAL "
                + "WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                sheetId, Date.valueOf(LocalDate.now()), sheetId);
        return jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId)
                .toLocalDate();
    }

    /**
     * The sheet's next claim number: 1 for its first, then 2, and so on. The sheet's row stays
     * locked until the transaction ends, so two claims opened at once get different numbers, and a
     * number is never given twice.
     */
    public long nextClaimNumber(String sheetId) {
        today(sheetId);
        jdbc.update("UPDATE sheet SET claim_numbers = claim_numbers + 1 WHERE id = ?", sheetId);
        return jdbc.queryForObject("SELECT claim_numbers FROM sheet WHERE id = ?", Long.class, sheetId);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, Date.valueOf(today));
    }
}
