package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import java.math.BigDecimal;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim the sheet's next number; a voided claim keeps it (and it is never reused).
 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
 *  bound it to, else its person's grade's rate in force on the claim's date, at least the sheet's floor, plus its late charge then; with no rate it stays live. The user who opened a claim may not settle it.
 *  A clerk may settle a claim only when that due is at or below the sheet's clerk limit (a due of n/a
 *  is within any limit); a steward settles anything.
 *  A claim dated in a closed period cannot change status at all. */
public class ApplyClaimStatus {
    public void apply(@Val ClaimStatusChange change, @Val Claim claim, Sheets sheets, People people,
            Figures figures, ClosedPeriods closedPeriods, Settings settings)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        if (!change.action().allowedFrom(claim.getStatus())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
        }
        if (change.action() == ClaimAction.SETTLE && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(change.user())) {
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        BigDecimal due = null;
        if (change.action() == ClaimAction.SETTLE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            due = claim.isStated() ? claim.getStatedDue() : figures.live(claim, grade);
            if (due != null) due = due.add(figures.charge(claim, due));
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            if (limit != null && due != null && due.compareTo(limit) > 0
                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK) {
                throw new ClaimStatusRefusedException("A clerk cannot settle a claim whose due is over the clerk limit");
            }
        }
        claim.setStatus(change.action().to());
        if (change.action() == ClaimAction.OPEN) {
            claim.setNumber(sheets.nextClaimNumber(claim.getSheetId()));
            claim.setOpenedBy(change.user());
        }
        if (change.action() == ClaimAction.SETTLE) {
            claim.setDue(due);
        }
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order (people in list order, each
 *  person's newest claim first), so their numbers follow that order. Each is opened as a single
 *  open would be — its own audit line, then the figures it moved; one that cannot be opened (or is
 *  not on the sheet) is left as it is and counted as refused. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpen bulk, Claims claims, People people,
            Sheets sheets, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            Audit audit, Out<BulkOpenResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.OPEN, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        int opened = 0;
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
                Claim claim = claims.find(sheetId, listed.getId());
                Snapshot before = rollup.snapshot(sheetId);
                try {
                    apply.apply(change, claim, sheets, people, figures, closedPeriods, settings);
                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                    continue;
                }
                claims.save(claim);
                record.record(change, claim, people, audit);
                rollup.record(sheetId, before, bulk.user());
                opened++;
            }
        }
        result.set(new BulkOpenResult(opened, bulk.claimIds().size() - opened));
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The sheets and their "today". A sheet starts with the real date the first time it is loaded;
 * from then on {@link #today(String)} is the only date the app uses for that sheet — never the
 * real clock.
 */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today, starting the sheet at the real date when it has never been used. */
    public LocalDate today(String sheetId) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, ? FROM DUAL "
                + "WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                sheetId, Date.valueOf(LocalDate.now()), sheetId);
        return jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId)
                .toLocalDate();
    }

    /**
     * The sheet's next claim number: 1 for its first, then 2, and so on. The sheet's row stays
     * locked until the transaction ends, so two claims opened at once get different numbers, and a
     * number is never given twice.
     */
    public long nextClaimNumber(String sheetId) {
        today(sheetId);
        jdbc.update("UPDATE sheet SET claim_numbers = claim_numbers + 1 WHERE id = ?", sheetId);
        return jdbc.queryForObject("SELECT claim_numbers FROM sheet WHERE id = ?", Long.class, sheetId);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, Date.valueOf(today));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The periods of each sheet. */
@Repository
public class Periods {

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY from_date", Periods::period, sheetId);
    }

    /** The period of this name on this sheet, or null when there is none. Locks its row for the
     *  rest of the transaction. */
    public Period find(String sheetId, String name) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND name = ? FOR UPDATE", Periods::period, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** The closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period closedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
    }

    /** Close the period, fixing its due-total. */
    public void close(Period period, BigDecimal total) {
        jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ?",
                total, period.sheetId(), period.name());
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen(Period period) {
        jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                period.sheetId(), period.name());
    }

    private static Period period(ResultSet rs, int i) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getDate("from_date").toLocalDate(),
                rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"));
    }
}

